export default{is_type:function(x,type){if("object"==type)return"object"===typeof x&&null!=x;if("array"==type)return Array.isArray(x);if("function"==type)return"function"===typeof x;if("string"==type)return"string"===typeof x;if("float"==type)return!isNaN(parseFloat(x))&&!isNaN(x-0);if("integer"==type)return!isNaN(x)&&parseInt(Number(x))==x&&!isNaN(parseInt(x,10));return false},is_object:function(x){return this.is_type(x,"object")},is_array:function(x){return this.is_type(x,"array")},is_function:function(x){return this.is_type(x,"function")},is_string:function(x){return this.is_type(x,"string")},is_float:function(x){return this.is_type(x,"float")},is_integer:function(x){return this.is_type(x,"integer")},sleep:function(ms){return new Promise(res=>setTimeout(res,ms))},clone:function(x){if(this.is_array(x)){return x.map(item=>this.clone(item))}else if(!this.is_object(x)){return x}let new_obj={};for(var prop_name in x){new_obj[prop_name]=this.clone(x[prop_name])}return new_obj},is_datetime_type:function(type,subtype){var type_list=[];if("date"==subtype){type_list=["datetimesecond","datetime","date","yearmonth","dob","dod"]}else if("time"==subtype){type_list=["timesecond","timesecond_notz","time","time_notz"]}else if("second"==subtype){type_list=["datetimesecond","timesecond","timesecond_notz"]}else if("timezone"==subtype){type_list=["datetimesecond","datetime","timesecond","time"]}else{type_list=["datetimesecond","datetime","date","yearmonth","dob","dod","timesecond","timesecond_notz","time","time_notz"]}return type_list.includes(type)},get_datetime_format:function(format,am_pm=false,long_form=false){var resolved_format=format;if("yearmonth"==format){resolved_format="MMMM, YYYY"}else if("dob"==format||"dod"==format){resolved_format="MMM D, YYYY"}else if(this.is_datetime_type(format,"date")){resolved_format=(long_form?"dddd, MMMM Do":"MMM D")+", YYYY";if("date"!=format){resolved_format+=" @ "+this.get_time_format(am_pm,this.is_datetime_type(format,"second"),long_form)}}else if(this.is_datetime_type(format,"time")){resolved_format=this.get_time_format(am_pm,this.is_datetime_type(format,"second"),false)}return resolved_format},get_time_format:function(am_pm=false,seconds=false,timezone=false){let h=am_pm?"h":"H";let s=seconds?":ss":"";let a=am_pm?"a":"";let z=timezone?" z":"";return`${h}:mm${s}${a}${z}`},uc_first:function(str){return String(str).charAt(0).toUpperCase()+String(str).slice(1)},uc_words:function(str){return String(str).replace(/(^[a-z]| [a-z])/g,match=>match.toUpperCase())},ordinal_suffix(number){let tens=number%10,hundreds=number%100;return number+(1==tens&&11!=hundreds?"st":2==tens&&12!=hundreds?"nd":3==tens&&13!=hundreds?"rd":"th")}};
